def change_base(x, base):
    if base < 2 or base > 9:
        raise ValueError("Base must be between 2 and 9.")

    if x == 0:
        return "0"

    digits = []
    while x > 0:
        digits.append(str(x % base))
        x //= base

    return ''.join(reversed(digits))

# Approach: Convert the number to the desired base by repeatedly dividing the number by the base and collecting the remainders. The remainders represent the digits of the number in the new base, which are then reversed to form the final string representation.
