def encode(message):
    vowels = 'aeiouAEIOU'
    encoded_message = []

    for char in message:
        if char.isalpha():
            # Swap case
            if char.islower():
                char = char.upper()
            else:
                char = char.lower()

            # Replace vowels
            if char in vowels:
                # Find the next vowel
                next_vowel = chr((ord(char) - ord('a') + 2) % 26 + ord('a'))
                encoded_message.append(next_vowel)
            else:
                encoded_message.append(char)
        else:
            encoded_message.append(char)

    return ''.join(encoded_message)

# Approach: The function iterates over each character in the input message. It swaps the case of each letter and replaces vowels with the letter two places ahead in the alphabet. Non-letter characters are added to the result without modification.
