def is_nested(s):
    stack = []
    nested = False
    for char in s:
        if char == '[':
            stack.append(char)
        elif char == ']':
            if stack:
                stack.pop()
                if stack:
                    nested = True
            else:
                return False
    return nested and not stack

# Approach: Use a stack to track opening brackets. If a closing bracket is encountered, pop from the stack. If the stack is not empty after popping, it means there was a nested bracket. The string is valid if the stack is empty at the end and there was at least one nested bracket.
